    let profile = {};

    this.fetchBasicInfo(userId).then(info => {
      profile.name = info.name;
      profile.email = info.email;
    });

    this.fetchPreferences(userId).then(prefs => {
      profile.theme = prefs.theme;
      profile.language = prefs.language;
